import { getSuggestions } from '@projexlight/sdk-recommendation';
const { suggestions } = await getSuggestions({
  tenant_id, persona_id: ae.id,
  subject: { kind: 'deal', id: deal_id },
  domain: 'next-best-action',
  top_k: 5,
});

import { recordFeedback } from '@projexlight/sdk-recommendation';
await recordFeedback({
  suggestion_id, item_id: 'send-proposal',
  action: 'accept', persona_id: ae.id,
});

import { publishModel } from '@projexlight/sdk-recommendation';
await publishModel({
  tenant_id, domain: 'content-related', version: '1.0.0',
  algo: 'content-vector-similarity',
  config: { vector_source: 'sdk-knowledge-rag', top_k_default: 5 },
});

subscribeEvents('lead_scoring.score.changed.v1', async (e) => {
  if (e.payload.new_score < 70) return;
  await getSuggestions({ subject: { kind: 'lead', id: e.payload.lead_id }, domain: 'next-best-action' });
});
